import {mountGarden} from './garden.js';
import {mountAuction} from './auction.js';
const root=document.getElementById('lab');let cleanup;
function showMenu(){try{const link=new URL(location.href);link.searchParams.delete('game');history.replaceState(null,'',link);}catch{}cleanup?.destroy?.();if(typeof cleanup==='function')cleanup();cleanup=null;root.className='lab-home';root.innerHTML=`<header class="lab-header"><a href="../">AFTER YOU</a><span>下一局</span></header><main><h1>这次，换一种乐趣。</h1><p class="lab-lead">两个不同方向的短局。选一个，看看会不会想再试一次。</p><div class="lab-choices"><button id="choose-garden" class="lab-choice"><span class="lab-choice-art">🌼 🐝 🌧️</span><h2>组合花园</h2><p>放下一张牌，让整个小世界运转。养蜂、喂猫、孵蛋，凑出你自己的连锁。</p><span class="lab-choice-foot">12 步策略 · 摆放与构筑</span></button><button id="choose-auction" class="lab-choice"><span class="lab-choice-art">🧱 🎙️ 🤖</span><h2>万物拍卖所</h2><p>用一句话，把怪东西卖给三位挑剔买家。换个说法，他们会愿意出多少？</p><span class="lab-choice-foot">3 件拍品 · 创意与 AI 反应</span></button></div><p class="lab-note">这是两种新方向。你的选择和真实感受，决定下一版做什么。</p></main>`;document.getElementById('choose-garden').addEventListener('click',()=>open('garden'));document.getElementById('choose-auction').addEventListener('click',()=>open('auction'));}
function open(which){try{const link=new URL(location.href);link.searchParams.set('game',which);history.replaceState(null,'',link);}catch{}root.className='lab-stage';root.replaceChildren();cleanup=which==='garden'?mountGarden(root,{onExit:showMenu}):mountAuction(root,{onExit:showMenu});window.scrollTo({top:0,behavior:'instant'});}
const initialGame=new URL(location.href).searchParams.get('game');if(initialGame==='garden'||initialGame==='auction')open(initialGame);else showMenu();
